from sec_common import *
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.font_manager import FontProperties

def main():
 out=HERE/'report';out.mkdir(exist_ok=False);a=HERE/'analysis-v2';s=pd.read_csv(a/'summary.csv');c=pd.read_csv(a/'curves.csv');w=pd.read_csv(a/'winner-retention.csv');pairs=pd.read_csv(HERE/'pairs/summary.csv');clusters=pd.read_csv(HERE/'pairs/e0-clusters.csv');annual=pd.read_csv(a/'annual.csv');scope=read(HERE/'scope.json');font=FontProperties(fname='/System/Library/Fonts/Supplemental/Arial Unicode.ttf');plt.rcParams.update({'font.family':font.get_name(),'axes.unicode_minus':False,'font.size':10});colors={'IX':'#5279bd','I':'#c66532'}
 fig,axs=plt.subplots(4,2,figsize=(15.5,14))
 for n,k in enumerate(GROUPS):
  for p,col in colors.items():
   g=c[(c.group==k)&(c.policy==p)];r=s[(s.group==k)&(s.policy==p)].iloc[0];d=pd.to_datetime(g.date)
   axs[n,0].plot(d,g.nav/1e4,label=f'{p} 收益{r.net_return:+.1%}',color=col,lw=1.3);axs[n,1].plot(d,g.drawdown*100,label=f'{p} 最大回撤{r.max_drawdown:.1%}',color=col,lw=1.1)
  axs[n,0].axhline(100,color='#aaa',ls='--',lw=.7);axs[n,0].set_title(f'{GROUPS[k][0]}｜{scope["counts"][k]}股池｜账户净值（万元）');axs[n,1].set_title(f'{GROUPS[k][0]}｜日收盘回撤');axs[n,1].set_ylim(-80,2);axs[n,1].set_ylabel('%')
 for ax in axs.flat:ax.grid(alpha=.15);ax.legend(fontsize=9)
 fig.suptitle('固定四板块：原IX vs 保留E0退出的I｜各100万元｜2021-01-04—2026-10-16',fontsize=16);fig.text(.5,.012,'排序/初仓15%/新增投入90%/最多6股不变；原价、整数股数、权益、费用、T+1。当前成员和市值快照开发检验，非样本外。',ha='center',fontsize=10);fig.tight_layout(rect=(0,.035,1,.97));fig.savefig(out/'account-comparison.png',dpi=145);plt.close(fig)
 names=['寒武纪','源杰科技','中际旭创','新易盛','艾力斯','上海银行'];fig,ax=plt.subplots(figsize=(11,5.5));x=np.arange(len(names));ww=w.set_index('name').reindex(names)
 for j,p in enumerate(colors):ax.bar(x+(j-.5)*.36,ww[p+'_pnl']/1e4,width=.36,label=p,color=colors[p])
 ax.set_xticks(x,names);ax.axhline(0,color='#777',lw=.8);ax.set_ylabel('实际账户累计净贡献（万元）');ax.set_title('长趋势保留有得有失：实际资金和占位路径也会改变');ax.grid(axis='y',alpha=.15);ax.legend();fig.text(.5,.015,'这是实际账户贡献，受成交次数和当时账户净值影响；不是同额买入的单股收益率。',ha='center',fontsize=9);fig.tight_layout(rect=(0,.05,1,1));fig.savefig(out/'winner-contributions.png',dpi=145);plt.close(fig)
 def table(df):return '<div class="scroll">'+df.to_html(index=False,border=0,escape=True)+'</div>'
 stats=s[['group','policy','net_return','max_drawdown','exposure','closed','win_rate','tail_trades','tail_pnl','ordinary_pnl','open_pnl']].copy();stats.group=stats.group.map(lambda k:GROUPS[k][0])
 for k in ['net_return','max_drawdown','exposure','win_rate']:stats[k]=stats[k].map(lambda x:f'{x:.2%}')
 for k in ['tail_pnl','ordinary_pnl','open_pnl']:stats[k]=stats[k].map(lambda x:f'{x/1e4:+.2f}万')
 stats.columns=['板块','政策','总收益','最大回撤','平均仓位','闭合交易','胜率','尾部笔数','尾部净贡献','普通净贡献','未闭合净贡献'];stats=table(stats)
 pair=pairs[['group','pairs','both_closed','IX_mean_return','I_mean_return','median_difference','I_better_fraction','tail_created','tail_lost']].copy();pair.group=pair.group.map(lambda k:GROUPS[k][0])
 for k in ['IX_mean_return','I_mean_return','median_difference','I_better_fraction']:pair[k]=pair[k].map(lambda x:f'{x:.2%}')
 pair.columns=['板块','配对','均已退出','IX均值','I均值','I−IX中位数','I较好占比','新增近似尾部','失去近似尾部'];pair=table(pair)
 win=w.copy();win.group=win.group.map(lambda k:GROUPS[k][0]);win=win[['group','name','IX_pnl','I_pnl','IX_campaigns','I_campaigns','IX_held_days','I_held_days']]
 for k in ['IX_pnl','I_pnl']:win[k]=win[k].map(lambda x:f'{x/1e4:+.2f}万')
 win.columns=['板块','股票','IX净贡献','I净贡献','IX周期','I周期','IX持股日','I持股日'];win=table(win)
 year=annual.pivot(index=['group','year'],columns='policy',values='net_return').reset_index();year.group=year.group.map(lambda k:GROUPS[k][0]);year.I=year.I.map(lambda x:f'{x:+.2%}');year.IX=year.IX.map(lambda x:f'{x:+.2%}');year.columns=['板块','年度','I','IX'];year=table(year)
 cl=clusters.groupby('group').agg(clusters=('symbol','size'),mean_difference=('difference','mean')).reset_index();cl.group=cl.group.map(lambda k:GROUPS[k][0]);cl.mean_difference=cl.mean_difference.map(lambda x:f'{x:+.2%}');cl.columns=['板块','E0段簇数','每簇均权I−IX'];cl=table(cl)
 body=f'''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SEC-EXIT-I 固定四板块退出对照</title><style>body{{font:16px/1.75 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;color:#253246;max-width:1240px;margin:auto;padding:32px 20px;background:#f7f9fc}}h1{{font-size:30px;line-height:1.35}}h2{{font-size:23px;margin-top:35px}}.card{{background:#fff;padding:22px 26px;border:1px solid #dfe5ed;border-radius:12px;margin:22px 0}}.lead{{font-size:20px}}.muted{{color:#687386;font-size:14px}}table{{border-collapse:collapse;width:100%;font-size:14px;background:#fff}}th,td{{border-bottom:1px solid #e2e7ed;padding:8px 10px;text-align:right;white-space:nowrap}}th:first-child,td:first-child{{text-align:left}}.scroll{{overflow:auto}}img{{width:100%;height:auto}}a{{color:#245eaf}}summary{{cursor:pointer}}details{{margin:18px 0}}</style><h1>股票层保留E0退出：四池收益均提高，风险取舍各不相同</h1><p class="muted">SEC-EXIT-I · 2021-01-04—2026-10-16 · 各账户100万元 · 半导体126股 / 通信43股 / 创新药48股 / 银行39股</p><div class="card lead">I收益分别为 <b>+205.89%、+492.84%、+25.55%、+8.28%</b>，均高于原IX。但半导体回撤升至 <b>68.86%</b>，创新药升至 <b>44.21%</b>；通信回撤基本不变，银行改善。支持保留I作为重要股票层对照，尚不支持统一替换或称风险目标已达成。</div>{stats}<p class="muted">净≥30%已闭合交易为尾部；30%不是止盈。总净损益=尾部+全部普通+未闭合净贡献。未闭合已计入净值但不计闭合胜率。四组是各自独立账户，不是400万元共同组合。</p><img src="account-comparison.png" alt="四板块I/IX账户净值与回撤"><h2>收益提高来自哪里，代价是什么</h2><p><b>半导体：</b>I尾部贡献416.22万元，IX为158.12万元；但普通交易损耗从155.98万元扩大至222.10万元，最大回撤58.32%→68.86%。收益提高依赖少量长赢家，不能称普通损耗已控制好。2022年I亏33.46%，IX亏18.21%。</p><p><b>通信设备：</b>I尾部贡献683.48万元，IX为379.46万元；普通损耗也从73.22万元扩大至172.92万元。I回撤48.68%、IX48.56%，基本持平；I并非每年都更好，2025和2026本区间年度收益均低于IX。</p><p><b>创新药：</b>I从亏13.00%转为赚25.55%，尾部贡献约翻倍，普通损耗仍变大，回撤38.71%→44.21%。这只是公开创新药指数当前成员与原合格池的交集研究。</p><p><b>银行：</b>I收益8.28%、IX亏10.50%，回撤37.54%→31.53%。I普通闭合交易接近相抵（+0.37万元），费用9.96万→3.14万元，少试错/少交易成本的贡献较明显；收益绝对值仍不高。</p><p>四池I闭合交易158/172/217/174次，IX为736/738/823/606次；平均仓位提高至76%—82%。初仓规则没有变，持有更久带来更高实际暴露，赢家自然增长也改变后续仓位。这里的收益增加同时包含退出时点、资金复利和占位路径，不能全部算成同笔卖出价格差。</p><details><summary>展开逐年收益（2026仅至10月16日，全部为已见开发历史）</summary>{year}</details><h2>同一入场事件的配对，说明了什么</h2>{pair}<p>11689个原IX参与段内首次全资格事件，保留11670对；下一市场日源缺口4、退出源缺口12、区间内无后续买入3，全部单列。归一化配对使用同一买入时点/价格和各自退出；价格/成本为旧信号价格近似，<b>不是资金账户收益</b>，不模拟印花税、最小手数和真实可成交限制。</p><p>I持有通常由8—9个价格观察延长至34—38个；约64%—71%的已闭合配对收益更低，中位差均为负。半导体/通信事件均值被少数长涨拉高；创新药/银行均值无改善。长期持有确实留下更多大涨，也放大许多失败尝试，不能用更慢退出保证每笔更好。</p><details><summary>展开重复长趋势加权问题</summary><p>多个IX小段可能都映射同一个E0长段，同一段I收益会被多次计算。按股票/E0段合并后每簇等权，四池平均差额均为负：</p>{cl}<p>这说明事件均值对覆盖方式敏感；不能把“新增377个尾部配对”理解为真实账户可独立赚377次。正式结论以有限资金账户为准，也不报告把重叠事件当独立样本的显著性。</p></details><details><summary>展开最大正反差异的量价轨迹（事后归因，不用于选规则）</summary><img src="../technical/paired-price-review.png" alt="量价退出正反例"></details><h2>大赢家保留：源杰改善，寒武纪和新易盛并未改善</h2><img src="winner-contributions.png" alt="大赢家的实际账户贡献">{win}<p>源杰科技：I于2025-07-03买入、2026-07-21退出，该周期净收益约929%、贡献134.66万元；两次周期合计贡献130.36万元，IX合计9.98万元。它是半导体I收益改善的重要来源。中际旭创贡献也从39.54万元增至59.65万元。</p><p>但寒武纪贡献从IX的+7.44万元变为I的−4.81万元，新易盛从+56.69万元降到+12.63万元。持股日更多不等于抓住了正确的那一段。</p><p><b>可核对的占位例子：</b>2023-02-24寒武纪满足I/IX共同买入资格，但I账户六槽已持峰岹科技、龙芯中科、兆易创新、汇成股份、通富微电、和林微纳；IX次日买入的周期最终赚约100.69%。2025-07-03新易盛同样合格，但I六槽被锐捷网络、移远通信、星网锐捷、汇绿生态、华测导航、海能达占用；IX次日买入的周期赚约172.90%。I当时分别还有11.88万/39.75万元现金，槽位也会独立阻止买入。</p><p>这不是新的入场信号缺失，而是保留E0持仓后的资源竞争。它支持后续单独研究交接问题，<b>不证明加快轮换必然更好</b>；旧主动轮换A/B/C/D已有失败，本轮没有重做或增加换仓。</p><h2>范围、规则与核验</h2><p>三个行业沿原合格池。创新药使用<a href="https://oss-ch.csindex.com.cn/static/html/csindex/public/uploads/file/autofile/cons/931152cons.xls">中证官网931152完整成分表</a>（表内2026-10-23）50股，与原池交集48股；京新药业、益方生物在原合格池外，保留排除记录。也保存了<a href="https://q.10jqka.com.cn/gn/detail/code/308014/">同花顺创新药页</a>核查，未把其首页10行当完整名单。官方定义见<a href="https://oss-ch.csindex.com.cn/static/html/csindex/public/uploads/indices/detail/files/zh_CN/931152factsheet.pdf">指数说明</a>。</p><p>创新药跨四个原行业。资格仍按成员真实原行业E0/当日观察/RS准备计算，只有容量统一到固定创新药主题；没有伪造主题E0，没有对四个子行业分别加2股限制。四池均按原RS-H1个股排序、最多六股、单股初仓整户净值15%、新增投入90%，不主动换仓。所有历史均为当前存续/市值/成员快照开发检验，不能称时点全池或样本外。</p><p>I与IX买入事件在256股全部历史中零差异；I只按E0结构/保护点退出，IX额外按原冷态/急跌退出。20个原投影核验、12个物理信号前缀、2368个独立配对价格/退出检查通过。有效8账户11200日日账独立原价/权益/股数/费用核对最大差0，5600次候选列表一致；半导体和通信的IX完整金融JSON及各1400日日账与旧结果完全一致。截断输入至2023-12-29后5816行日账及5816行决策精确一致。</p><p><b>技术失败保留：</b>首批8账户容量适配误用每行业2股，作废保存在accounts/；修正为冻结约定六股后，有效结果在accounts-v2/。经济重跑一次，仅修复容量违约，策略/参数结果后修订0。分析器首次导入重名失败另行保存，未重跑经济。没有覆盖旧模型或旧账，也没有新增股票行情下载/实盘。</p><div class="card"><a href="../CONCLUSION.md">完整结论</a> · <a href="../PROTOCOL.md">事前协议</a> · <a href="../IMPLEMENTATION_CORRECTION.md">容量修复说明</a> · <a href="../scope.csv">全股票池</a> · <a href="../analysis-v2/summary.csv">账户汇总CSV</a> · <a href="../analysis-v2/campaigns.csv">实际持仓周期</a> · <a href="../pairs/events.csv">全部配对</a> · <a href="../analysis-v2/missed-winner-cases.json">错过案例</a> · <a href="../analysis-v2/accounting.json">独立核账</a> · <a href="../technical/prefix-identity-v2.json">物理前缀</a></div></html>'''
 (out/'index.html').write_text(body);print('report written')
if __name__=='__main__':main()
